// spinnerFrames matches the bubbles/spinner Dot frames used by the activity
// TUI, so a CLI spinner here visually matches `entire activity`.
var spinnerFrames = []string{"⣾", "⣽", "⣻", "⢿", "⡿", "⣟", "⣯", "⣷"}

const (
	spinnerInterval = 100 * time.Millisecond
	// spinnerInitialDelay is how long an operation must run before the
	// spinner appears at all. Faster operations don't get a spinner —
	// avoids flicker on warm runs that complete in under a quarter second.
	spinnerInitialDelay = 250 * time.Millisecond
)

// startSpinner prints msg followed by an animated spinner to w when the
// operation takes longer than spinnerInitialDelay. stop(true) leaves
// "✓ msg" on the line; stop(false) erases the line and writes nothing.
// On non-terminal writers the animation is omitted but stop(true) still
// prints the completion line.
func startSpinner(w io.Writer, msg string) func(success bool) {
	_, stop := startUpdatableSpinner(w, msg)
	return stop
}

// startUpdatableSpinner is startSpinner's variant for an operation whose
// status text changes while it runs (e.g. "session 2/5 · turn 3/10"). update
// replaces the message the next frame draws — or, on the non-animated path,
// the message stop's completion line uses. update is safe to call at any
// point, including before the spinner's first frame draws and after stop
// returns. stop behaves exactly like startSpinner's, rendering whichever
// message update last set (or msg, if update was never called).
//
// The live animation is emitted only when w both is a terminal and can render
// ANSI (interactive.ShouldStyle) — the frames use cursor-control escapes
// (\r\033[K), which a legacy console that can't handle ANSI (e.g.
// TERM=cygwin) renders as literal "←[K" garbage, and which NO_COLOR asks us
// to suppress. When styling is off we fall back to the completion-line-only
// path, so no escape byte is ever written to such a writer.
func startUpdatableSpinner(w io.Writer, msg string) (update func(string), stop func(success bool)) {
	var mu sync.Mutex
	current := msg
	setMsg := func(m string) {
		mu.Lock()
		current = m
		mu.Unlock()
	}
	getMsg := func() string {
		mu.Lock()
		defer mu.Unlock()
		return current
	}

	// ShouldStyle already returns false for a non-terminal writer, so this
	// single gate also covers the plain non-TTY case.
	if !interactive.ShouldStyle(w) {
		return setMsg, func(success bool) {
			if success {
				fmt.Fprintf(w, "✓ %s\n", getMsg())
			}
		}
	}

	done := make(chan struct{})
	stopped := make(chan struct{})
	go func() {
		defer close(stopped)
		select {
		case <-done:
			return // operation finished before the spinner would appear
		case <-time.After(spinnerInitialDelay):
		}

		"Plugin index URL (overrides "+pluginIndexEnvVar+" and the built-in default)")
}

type remoteInstallFlags struct {
	force, yes, noDeps, allowUnverified bool
	pin, index                          string
}

func runRemoteInstall(ctx context.Context, cmd *cobra.Command, src installSource, flags remoteInstallFlags) error {
	out, errOut := cmd.OutOrStdout(), cmd.ErrOrStderr()
	ctx = withPluginProgress(ctx, errOut)

	repoURL := src.Ref
	var trusted bool
	var expectedName string

	// Both paths need the catalog: one to resolve a name, the other for the
	// trust check. Sync once. An unreachable index is fatal only for the
	// name-resolution path; a URL install degrades to "not listed".
	stopIndex := startPluginStep(ctx, "Checking plugin index...")
	idx, idxErr := SyncPluginIndex(ctx, resolvePluginIndexURL(flags.index), false)
	stopIndex()

	if src.Kind == installFromIndex {
		if idxErr != nil {
			return fmt.Errorf("resolve %q via plugin index: %w", src.Ref, idxErr)
		}
		entry := idx.Find(src.Ref)
		if entry == nil {
			// Bare names never resolve to local files (see
			// parseInstallSource), but a user who typed one expecting a
			// path install deserves the pointer.
			if _, statErr := os.Stat(src.Ref); statErr == nil {
				return fmt.Errorf("plugin %q is not in the index; to install the local file, use an explicit path: entire plugin install ./%s", src.Ref, src.Ref)
			}
			return fmt.Errorf("plugin %q is not in the index; pass the repository URL to install from a specific repo (try 'entire plugin search %s')", src.Ref, src.Ref)
		}
		if len(entry.Platforms) > 0 && !slices.Contains(entry.Platforms, runtime.GOOS) {
			fmt.Fprintf(errOut, "Warning: index lists %q for %s only; this is %s — continuing anyway.\n",
				src.Ref, strings.Join(entry.Platforms, "/"), runtime.GOOS)
		}
		repoURL = entry.RepoURL
		// The user asked for this catalog name; the repo must not install
		// under a different one. Index installs never prompt, so this is the
		// only thing tying the request to what lands on PATH.
		expectedName = entry.Name
		trusted = true
	} else if entry := idx.FindByRepoURL(repoURL); idxErr == nil && entry != nil {
		// A listed URL installs without a prompt, so the catalog entry is the
		// only thing tying the request to what lands on PATH. Taking the name
		// from it means the reconciliation guard applies here too — otherwise
		// the remote names itself and --force replaces whatever it picked, with
		// no prompt at all.
		expectedName = entry.Name
		trusted = true
	}

	if !trusted {
		// An untrusted source cannot proceed unconfirmed: automation never
		// reaches this prompt, because the non-interactive path fails above
		// with the --yes hint.
		proceed, err := confirmInstallOrCancel(ctx, errOut,
			fmt.Sprintf("Install from %s? The repository is not listed in the plugin index.", redactURL(repoURL)),
			flags.yes)
		if err != nil || !proceed {
			return err
		}
	}

	// expectedName is set on the index path and empty on the URL path, where
	// the repository names itself.
	res, err := InstallPluginFromRepo(ctx, repoURL, expectedName, RemoteInstallOptions{
		Pin: flags.pin, Force: flags.force, AllowUnverified: flags.allowUnverified,
	})
	if err != nil {
		return fmt.Errorf("install plugin: %w", err)
	}
	if res.ReplacedFrom != "" {
		fmt.Fprintf(errOut, "Warning: replaced plugin %q, which was installed from %s.\n",
